package com.smarttask.config;
import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler {@ExceptionHandler(NoSuchElementException.class) public ResponseEntity<?> missing(RuntimeException e){return ResponseEntity.status(404).body(Map.of("message",e.getMessage()));}@ExceptionHandler(IllegalArgumentException.class) public ResponseEntity<?> invalid(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}@ExceptionHandler(MethodArgumentNotValidException.class) public ResponseEntity<?> invalidFields(MethodArgumentNotValidException e){String msg=e.getBindingResult().getFieldErrors().stream().findFirst().map(x->x.getField()+": "+x.getDefaultMessage()).orElse("Invalid request.");return ResponseEntity.badRequest().body(Map.of("message",msg));}}
